444	    fn infer_pattern_segment(
445	        &mut self,
446	        mut segment: UntypedPatternBitArraySegment,
447	        is_last_segment: bool,
448	    ) -> TypedPatternBitArraySegment {
449	        // If the segment doesn't have an explicit type option we add a default
450	        // one ourselves if the pattern is unambiguous: literal strings are
451	        // implicitly considered utf-8 encoded strings, while floats are
452	        // implicitly given the float type option.
453	        if !segment.has_type_option() {
454	            match segment.value_unwrapping_assign() {
455	                Pattern::String { location, .. } => {
456	                    self.track_feature_usage(FeatureKind::UnannotatedUtf8StringSegment, *location);
457	                    segment.options.push(BitArrayOption::Utf8 {
458	                        location: SrcSpan::default(),
459	                    });
460	                }
461	
462	                Pattern::Float { location, .. } => {
463	                    self.track_feature_usage(FeatureKind::UnannotatedFloatSegment, *location);
464	                    segment.options.push(BitArrayOption::Float {
465	                        location: SrcSpan::default(),
466	                    })
467	                }
468	
469	                Pattern::Int { .. }
470	                | Pattern::Variable { .. }
471	                | Pattern::BitArraySize(_)
472	                | Pattern::Assign { .. }
473	                | Pattern::Discard { .. }
474	                | Pattern::List { .. }
475	                | Pattern::Constructor { .. }
476	                | Pattern::Tuple { .. }
477	                | Pattern::BitArray { .. }
478	                | Pattern::StringPrefix { .. }
479	                | Pattern::Invalid { .. } => (),
480	            }
481	        }
482	
483	        let has_non_utf8_string_option = segment.has_utf16_option() || segment.has_utf32_option();
484	
485	        let options: Vec<_> = segment
486	            .options
487	            .into_iter()
488	            .map(|option| {
489	                analyse::infer_bit_array_option(option, |value, type_| {
490	                    Ok(self.unify(value, type_, None))
491	                })
492	            })
493	            .try_collect()
494	            .expect("The function always returns Ok");
495	
496	        self.check_pattern_segment_size_expression(&options);
497	
498	        let segment_type = match bit_array::type_options_for_pattern(
499	            &options,
500	            !is_last_segment,
501	            self.environment.target,
502	        ) {
503	            Ok(type_) => type_,
504	            Err(error) => {
505	                self.error(Error::BitArraySegmentError {
506	                    error: error.error,
507	                    location: error.location,
508	                });
509	                self.environment.new_unbound_var()
510	            }
511	        };
512	
513	        // Track usage of the unaligned bit arrays feature on JavaScript so that
514	        // warnings can be emitted if the Gleam version constraint is too low
515	        if self.environment.target == Target::JavaScript
516	            && !self.current_function.has_javascript_external
517	        {
518	            for option in options.iter() {
519	                match option {
520	                    // Use of the `bits` segment type
521	                    BitArrayOption::Bits { location } => {
522	                        self.track_feature_usage(
523	                            FeatureKind::JavaScriptUnalignedBitArray,
524	                            *location,
525	                        );
526	                    }
527	
528	                    // Int segments that aren't a whole number of bytes
529	                    BitArrayOption::Size { value, .. } if segment_type.is_int() => match &**value {
530	                        Pattern::BitArraySize(BitArraySize::Int {
531	                            location,
532	                            int_value,
533	                            ..
534	                        }) if int_value % 8 != BigInt::ZERO => {
535	                            self.track_feature_usage(
536	                                FeatureKind::JavaScriptUnalignedBitArray,
537	                                *location,
538	                            );
539	                        }
540	                        Pattern::Int { .. }
541	                        | Pattern::Float { .. }
542	                        | Pattern::String { .. }
543	                        | Pattern::Variable { .. }
544	                        | Pattern::BitArraySize(_)
545	                        | Pattern::Assign { .. }
546	                        | Pattern::Discard { .. }
547	                        | Pattern::List { .. }
548	                        | Pattern::Constructor { .. }
549	                        | Pattern::Tuple { .. }
550	                        | Pattern::BitArray { .. }
551	                        | Pattern::StringPrefix { .. }
552	                        | Pattern::Invalid { .. } => (),
553	                    },
554	
555	                    BitArrayOption::Bytes { .. }
556	                    | BitArrayOption::Int { .. }
557	                    | BitArrayOption::Float { .. }
558	                    | BitArrayOption::Utf8 { .. }
559	                    | BitArrayOption::Utf16 { .. }
560	                    | BitArrayOption::Utf32 { .. }
561	                    | BitArrayOption::Utf8Codepoint { .. }
562	                    | BitArrayOption::Utf16Codepoint { .. }
563	                    | BitArrayOption::Utf32Codepoint { .. }
564	                    | BitArrayOption::Signed { .. }
565	                    | BitArrayOption::Unsigned { .. }
566	                    | BitArrayOption::Big { .. }
567	                    | BitArrayOption::Little { .. }
568	                    | BitArrayOption::Native { .. }
569	                    | BitArrayOption::Size { .. }
570	                    | BitArrayOption::Unit { .. } => (),
571	                }
572	            }
573	        }
574	
575	        let type_ = match segment.value.deref() {
576	            Pattern::Assign { pattern, .. } if pattern.is_discard() && segment_type.is_string() => {
577	                self.error(Error::BitArraySegmentError {
578	                    error: bit_array::ErrorType::VariableUtfSegmentInPattern,
579	                    location: segment.location,
580	                });
581	                self.environment.new_unbound_var()
582	            }
583	            Pattern::Variable { .. } if segment_type.is_string() => {
584	                self.error(Error::BitArraySegmentError {
585	                    error: bit_array::ErrorType::VariableUtfSegmentInPattern,
586	                    location: segment.location,
587	                });
588	                self.environment.new_unbound_var()
589	            }
590	            Pattern::Int { .. }
591	            | Pattern::Float { .. }
592	            | Pattern::String { .. }
593	            | Pattern::Variable { .. }
594	            | Pattern::BitArraySize(_)
595	            | Pattern::Assign { .. }
596	            | Pattern::Discard { .. }
597	            | Pattern::List { .. }
598	            | Pattern::Constructor { .. }
599	            | Pattern::Tuple { .. }
600	            | Pattern::BitArray { .. }
601	            | Pattern::StringPrefix { .. }
602	            | Pattern::Invalid { .. } => segment_type,
603	        };

